-- fbb37214 | ما الأصل في البيوع؟
UPDATE qa_questions SET
  answer = 'البيعُ عند ابن قدامة حدُّه: «مُبَادَلَةُ المالِ بِالمَالِ، تَمْلِيكًا، وتَمَلُّكًا» (المغني ج٦/ص٥)، وحكمُه ثابتٌ بالأدلّة الثلاثة لا بأصلٍ استصحابيٍّ مجرَّد: «والبَيْعُ جَائِزٌ بِالكِتَابِ والسُّنَّةِ والإجْمَاعِ»، و«أجْمَعَ المُسْلِمُونَ على جَوَازِ البَيْعِ فى الجُمْلَةِ» (ج٦/ص٧). ⚠️ ولفظُ ‹الأصل في البيع› لم يستعمله المغني في الإباحة أصلًا، وإنما استعمله في مسألةٍ أخرى: «لأنَّ الأَصْلَ في البَيْعِ الحُلُولُ» (ج٧/ص٢٤٦) — فالأولى بناءُ الحكم على نصوصه لا على صياغةٍ قاعديّةٍ متأخّرة. وأصلُه من الكتاب ﴿وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟﴾ [البقرة: ٢٧٥]، وشرطُ التراضي منصوصٌ معه في ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍۢ مِّنكُمْ﴾ [النساء: ٢٩] — وهو قيدٌ سقط من الجواب السابق مع كونه أصلَ الباب. وأمّا الغررُ فقيدٌ بالسنّة: «نَهَى عن بَيْع الغَرَرِ. رَوَاهُ مُسْلمٌ» (ج٦/ص٣١). وينعقد البيعُ على ضربين لا ضربٍ واحد: «الإِيجَابُ والقَبُولُ»، والمعاطاةُ «فهذا بَيعٌ صَحِيحٌ. نَصَّ عليه أحْمَدُ» (ج٦/ص٧).',
  reference = 'المغني لابن قدامة (ت التركي والحلو، دار عالم الكتب، ط٣ ١٤١٧هـ): ج٦/ص٥ (كتاب البيوع) وج٦/ص٧ وج٦/ص٣١؛ ومصحفُ المشروع: البقرة ٢٧٥، النساء ٢٩ | الكلمات المفتاحية: بيع، ربا، معاملات',
  evidence = 'حدُّ البيع في المغني ج٦/ص٥: «مُبَادَلَةُ المالِ بِالمَالِ، تَمْلِيكًا، وتَمَلُّكًا»، وحكمُه فيه: «والبَيْعُ جَائِزٌ بِالكِتَابِ والسُّنَّةِ والإجْمَاعِ»، ثم ساق أدلّته من الكتاب، منها قولُه تعالى ﴿وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟﴾ [البقرة: ٢٧٥]، و﴿إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍۢ مِّنكُمْ﴾ [النساء: ٢٩]. وأمّا الإجماع فقال ج٦/ص٧: «وأجْمَعَ المُسْلِمُونَ على جَوَازِ البَيْعِ فى الجُمْلَةِ»، وعلّله بالحاجة: «لأنَّ حاجَةَ الإِنْسانِ تَتَعَلَّقُ بما فى يَدِ صاحِبِه، وصاحِبُه لا يَبْذُلُه بغَيْرِ عِوَضٍ». وأمّا قيدُ الغرر فمُستَنَدُه في ج٦/ص٣١: «ما رُوِىَ عن النَّبِىِّ -صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ-، أنَّه نَهَى عن بَيْع الغَرَرِ. رَوَاهُ مُسْلمٌ».',
  verification_status = 'verified'
WHERE id = 'fbb37214-d995-40f8-bb9a-8c8ae557445d'
  AND reference = 'القرآن الكريم؛ المغني | الكلمات المفتاحية: بيع، ربا، معاملات'
  AND evidence = 'قال تعالى: ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾ [البقرة: 275].'
  AND answer = 'الأصل في البيوع الإباحة ما لم تتضمن ربا أو غرراً محرماً أو ظلماً.';

-- 8bc01d8b | ما المشروع عند وقوع الطلاق؟
UPDATE qa_questions SET
  answer = 'المشروعُ منصوصٌ لا مُحالٌ فيه على غيرِ نصّ: «وَطَلَاقُ السُّنَّةِ أَنْ يُطَلِّقَها طَاهِرًا مِنْ غَيْرِ جِمَاعٍ وَاحِدَةً، ثُمَّ يَدعَهَا حَتَّى تَنْقَضِىَ عِدَّتُهَا» (المغني ج١٠/ص٣٢٥)، فهذه أربعةُ قيودٍ: في طُهرٍ، لم يُصِبْها فيه، واحدةً، ثم يَدَعُها. وعلّةُ المنع من الطلاق في الحيض أو في طهرٍ أصابها فيه مذكورةٌ في الموضع نفسِه: «إذا طلَّقَ فى الحَيْضِ طَوَّل العِدَّةَ عليها … وإِذا طلَّقَ فى طُهْرٍ أصابَها فيه، لم يَأمنْ أن تكونَ حاملًا، فيَنْدمَ». فإن وقع في الحيض فالمشروعُ الرجعةُ ثم الإمهال: «مُرْهُ فَلْيُرَاجِعْهَا، ثُم لِيَتْرُكْهَا حَتَّى تَطْهُرَ، ثُم تَحِيضَ، ثُمَّ تَطْهُرَ» (ج١٠/ص٣٢٣، متّفق عليه). وتعتدُّ في بيت الزوج ﴿لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ﴾ [الطلاق: ١]، ومآلُ الأمر إلى أحد أمرين ﴿فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَٰنٍۢ﴾ [البقرة: ٢٢٩]. ⚠️ والطلاقُ ليس حكمًا واحدًا يُستفتى فيه على الإطلاق: «والطَّلاقُ على خمسةِ أضْرُبٍ؛ واجبٌ … ومكروهٌ، وهو الطَّلاقُ مِن غيرِ حاجةٍ إليه» (ج١٠/ص٣٢٣). والرجوعُ إلى القضاء إنما محلُّه الوقائعُ الخاصّة والنزاعُ في الألفاظ، لا أصلُ الحكم فإنه منصوص.',
  reference = 'المغني لابن قدامة (ت التركي والحلو، دار عالم الكتب، ط٣ ١٤١٧هـ): ج١٠/ص٣٢٣ (كتاب الطلاق) وج١٠/ص٣٢٥ (مسألة ١٢٤٧)؛ ومصحفُ المشروع: البقرة ٢٢٩، الطلاق ١ | الكلمات المفتاحية: طلاق، عدة، أسرة',
  evidence = 'متنُ الخِرَقيّ في المغني ج١٠/ص٣٢٥ (مسألة ١٢٤٧): «وَطَلَاقُ السُّنَّةِ أَنْ يُطَلِّقَها طَاهِرًا مِنْ غَيْرِ جِمَاعٍ وَاحِدَةً، ثُمَّ يَدعَهَا حَتَّى تَنْقَضِىَ عِدَّتُهَا»، وفسّره ابنُ قدامة بأنه «الطَّلاقُ الذى وافَقَ أمرَ اللَّهِ تعالى وأمْرَ رسولهِ -صلى اللَّه عليه وسلم-»، ونقل الاتّفاق عليه: «ولا خلافَ فى أنَّه إذا طلقَها فى طُهْرٍ لم يُصِبْها فيه، ثم تركَها حتى تَنْقَضِىَ عِدَّتُها، أنَّه مُصيبٌ للسُّنَّةِ». وإن وقع الطلاقُ في الحيض فالمنصوصُ في ج١٠/ص٣٢٣ حديثُ ابن عمر متّفقًا عليه: «مُرْهُ فَلْيُرَاجِعْهَا، ثُم لِيَتْرُكْهَا حَتَّى تَطْهُرَ، ثُم تَحِيضَ، ثُمَّ تَطْهُرَ، ثُمَّ إنْ شَاءَ أمْسَكَ بَعدُ، وإِنْ شَاءَ طَلَّقَ قَبْلَ أَنْ يَمَسَّ». وأصلُه من الكتاب ﴿ٱلطَّلَٰقُ مَرَّتَانِ ۖ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَٰنٍۢ﴾ [البقرة: ٢٢٩]، و﴿يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ﴾ [الطلاق: ١].',
  verification_status = 'verified'
WHERE id = '8bc01d8b-5bec-41fb-befb-d77110761831'
  AND reference = 'القرآن الكريم؛ المغني | الكلمات المفتاحية: طلاق، عدة، أسرة'
  AND evidence = 'قال تعالى: ﴿الطَّلَاقُ مَرَّتَانِ﴾ [البقرة: 229].'
  AND answer = 'يجب ضبط الألفاظ والرجوع لأهل العلم والقضاء المختص في الوقائع الخاصة؛ لأن الأحكام تختلف باختلاف الحال.';

-- 48179d96 | ما كفارة اليمين؟
UPDATE qa_questions SET
  answer = 'الكفّارةُ لا تجب بمجرَّد اليمين بل بالحِنث: «وَمَنْ وَجَبَتْ عَلَيْه بِالْحِنْثِ كَفَّارَةُ يَمينٍ، فَهُوَ مُخيَّرٌ» (المغني ج١٣/ص٥٠٦) — وهو قيدٌ سقط من الجواب السابق. ولغوُ اليمين لا كفّارة فيه ﴿لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ﴾ [المائدة: ٨٩]. والخصالُ الثلاث الأُوَل على التخيير بالإجماع: «أجْمَع أهلُ العلمِ، على أَنّ الحانِثَ فى يَمِينِه بالْخِيارِ؛ إِنْ شاءَ أَطْعَمَ، وإِنْ شاءَ كَسَا، وإِنْ شاءَ أَعْتَقَ». ⚠️ وأمّا الصيامُ فليس خصلةً رابعةً مخيَّرةً بل بدلٌ عند العجز، وضابطُه المنقولُ عن ابن عباس: «ما كان فى كتابِ اللَّه {أَوْ} فهو مُخَيَّرٌ فيه، وما كان {فَمَنْ لَمْ يَجِدْ} فالأوَّلُ الأوَّلُ». وفي المطعَمين أربعةُ أوصافٍ نصَّ عليها ج١٣/ص٥٠٧–٥٠٨ ولم يذكرها الجواب: أن يكونوا مساكينَ، «الثانى، أَنْ يكونُوا أحْرارًا»، «الثالث، أَنْ يكونُوا مسلمين»، «الرابعُ، أَنْ يكونُوا قد أَكلُوا الطَّعامَ». وللإطعام قَدْرٌ مقدَّر لا يُترك للعُرف: «لِكُلِّ مِسْكِينٍ مُدٌّ مِنْ حِنْطَةٍ أَوْ دَقيقٍ، أو رِطْلانِ خُبْزًا، أو مُدَّانِ تَمْرًا أو شَعِيرًا» (ج١٣/ص٥٠٩).',
  reference = 'المغني لابن قدامة (ت التركي والحلو، دار عالم الكتب، ط٣ ١٤١٧هـ): ج١٣/ص٥٠٦ (باب الكفارات، مسألة ١٨٠٤) وج١٣/ص٥٠٧–٥٠٨ وج١٣/ص٥٠٩ (مسألة ١٨٠٥)؛ ومصحفُ المشروع: المائدة ٨٩ | الكلمات المفتاحية: يمين، كفارة، صيام',
  evidence = 'قال ابنُ قدامة في المغني ج١٣/ص٥٠٦ (باب الكفارات): «الأَصْلُ فى كفّارَةِ اليَمِينِ، الكتابُ والسُّنَّةُ والإِجْماعُ»، ثم ساق آيةَ المائدة ٨٩، ونصُّها من مصحف المشروع: ﴿لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَٰنَ ۖ فَكَفَّٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَٰكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍۢ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍۢ﴾ [المائدة: ٨٩]. ومتنُ الخِرَقيّ في الموضع نفسِه: «وَمَنْ وَجَبَتْ عَلَيْه بِالْحِنْثِ كَفَّارَةُ يَمينٍ، فَهُوَ مُخيَّرٌ»، وضابطُ الترتيب فيه عن ابن عباس: «ما كان فى كتابِ اللَّه {أَوْ} فهو مُخَيَّرٌ فيه، وما كان {فَمَنْ لَمْ يَجِدْ} فالأوَّلُ الأوَّلُ». وقَدْرُ الإطعام في ج١٣/ص٥٠٩ (مسألة ١٨٠٥): «لِكُلِّ مِسْكِينٍ مُدٌّ مِنْ حِنْطَةٍ أَوْ دَقيقٍ، أو رِطْلانِ خُبْزًا، أو مُدَّانِ تَمْرًا أو شَعِيرًا».',
  verification_status = 'verified'
WHERE id = '48179d96-8caa-4b80-86e5-61aecff2b79d'
  AND reference = 'القرآن الكريم؛ المغني | الكلمات المفتاحية: يمين، كفارة، صيام'
  AND evidence = 'قال تعالى: ﴿فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ﴾ [المائدة: 89].'
  AND answer = 'إطعام عشرة مساكين أو كسوتهم أو تحرير رقبة، فمن لم يجد فصيام ثلاثة أيام.';

-- 6856c2ca | على من تجب الزكاة؟
UPDATE qa_questions SET
  answer = 'السؤالُ عمَّن تجب عليه، وجوابُه منصوصٌ في متن الخِرَقيّ: «والصَّدَقَةُ لَا تَجِبُ إلَّا عَلَى أحْرَارِ المُسْلِمِينَ» (المغني ج٤/ص٦٩)، أي «على حُرٍّ مُسْلِمٍ تَامِّ المِلْكِ»؛ فخرج الكافرُ «فلا خِلافَ فى أنَّه لا زكاةَ عليه»، وخرج العبدُ والمكاتَبُ «أنَّ العَبْدَ ليس بِتَامِّ المِلْكِ، فلم تَلْزَمْهُ زَكَاةٌ، كالمُكاتَبِ». ⚠️ وإطلاقُ ‹تحقق الشروط› يُوهم اشتراطَ البلوغ والعقل، والمنصوصُ خلافُه: «سَوَاءٌ كان كَبِيرًا أو صَغِيرًا، أو عَاقِلًا أو مَجْنُونًا»، بل «والصَّبِىُّ والمَجْنُونُ يُخْرِجُ عَنْهُمَا وَلِيُّهُما» (ج٤/ص٧٠) — وهو قولُ الأكثر، وخالف فيه أبو حنيفة ومن معه، فلا يُنقَل إجماعًا. ثم يُشترط في المال بلوغُ النصاب وحولانُ الحول: «لَا زَكَاةَ فِى مَالٍ حَتَّى يَحُولَ عَلَيْهِ الْحَوْلُ» (ج٤/ص٧٧). وأصلُ الوجوب ﴿وَءَاتُوا۟ ٱلزَّكَوٰةَ﴾ [البقرة: ٤٣]، وهي «أحَدُ أَرْكانِ الإسلامِ الخَمْسَة، وهى وَاجِبَةٌ بكِتابِ اللهِ تعالى، وسُنَّةِ رَسُولِه -صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ-، وإجْماعِ أُمَّتِهِ» (ج٤/ص٥).',
  reference = 'المغني لابن قدامة (ت التركي والحلو، دار عالم الكتب، ط٣ ١٤١٧هـ): ج٤/ص٥ (كتاب الزكاة) وج٤/ص٦٩ (مسألة ٤١٥) وج٤/ص٧٠ (مسألة ٤١٦) وج٤/ص٧٧؛ ومصحفُ المشروع: البقرة ٤٣ | الكلمات المفتاحية: زكاة، نصاب، حول',
  evidence = 'متنُ الخِرَقيّ في المغني ج٤/ص٦٩ (مسألة ٤١٥): «والصَّدَقَةُ لَا تَجِبُ إلَّا عَلَى أحْرَارِ المُسْلِمِينَ»، وفسّره ابنُ قدامة: «وهو أنَّ الزَّكَاةَ لا تَجِبُ إلَّا على حُرٍّ مُسْلِمٍ تَامِّ المِلْكِ، وهذا قولُ أكْثَرِ أهْلِ العِلْمِ»، وقال في الكافر: «فأمَّا الكَافِرُ فلا خِلافَ فى أنَّه لا زكاةَ عليه». ثم نصَّ على أن البلوغ والعقل ليسا شرطًا: «فأمَّا الحُرُّ المُسْلِمُ إذا مَلَكَ نِصَابًا خَالِيًا عن دَيْنٍ، فعليه الزكاةُ عندَ تَمَامِ حَوْلِه، سَوَاءٌ كان كَبِيرًا أو صَغِيرًا، أو عَاقِلًا أو مَجْنُونًا»، ومتنُ ج٤/ص٧٠ (مسألة ٤١٦): «والصَّبِىُّ والمَجْنُونُ يُخْرِجُ عَنْهُمَا وَلِيُّهُما». وشرطُ الحول ثابتٌ بحديث عائشة كما في ج٤/ص٧٧: «لَا زَكَاةَ فِى مَالٍ حَتَّى يَحُولَ عَلَيْهِ الْحَوْلُ». وأصلُ الوجوب من الكتاب ﴿وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ﴾ [البقرة: ٤٣].',
